// PlugAI project — ESP32-C3-DevKitM-1 (ESP-IDF v5.5)
// Two fully independent blinking LEDs:
//   LED1 (red,   GPIO4, 220 ohm) : 1.0 s period (500 ms on / 500 ms off)
//   LED2 (green, GPIO5, 220 ohm) : 0.4 s period (200 ms on / 200 ms off)
// Each LED is driven by its own FreeRTOS task using vTaskDelay, so the two
// blinkers never block or influence each other. Plain GPIO toggling only
// (no LEDC/PWM).

#include <stdio.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "driver/gpio.h"

#define LED1_GPIO        GPIO_NUM_4
#define LED2_GPIO        GPIO_NUM_5

#define LED1_ON_MS       500
#define LED1_OFF_MS      500

#define LED2_ON_MS       200
#define LED2_OFF_MS      200

static void task_led1(void *arg)
{
    (void)arg;
    for (;;) {
        gpio_set_level(LED1_GPIO, 1);
        vTaskDelay(pdMS_TO_TICKS(LED1_ON_MS));
        gpio_set_level(LED1_GPIO, 0);
        vTaskDelay(pdMS_TO_TICKS(LED1_OFF_MS));
    }
}

static void task_led2(void *arg)
{
    (void)arg;
    for (;;) {
        gpio_set_level(LED2_GPIO, 1);
        vTaskDelay(pdMS_TO_TICKS(LED2_ON_MS));
        gpio_set_level(LED2_GPIO, 0);
        vTaskDelay(pdMS_TO_TICKS(LED2_OFF_MS));
    }
}

void app_main(void)
{
    gpio_config_t out_cfg = {
        .pin_bit_mask = (1ULL << LED1_GPIO) | (1ULL << LED2_GPIO),
        .mode = GPIO_MODE_OUTPUT,
        .pull_up_en = GPIO_PULLUP_DISABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type = GPIO_INTR_DISABLE,
    };
    gpio_config(&out_cfg);

    // Start with both LEDs off (reset state is defined before any task runs).
    gpio_set_level(LED1_GPIO, 0);
    gpio_set_level(LED2_GPIO, 0);

    printf("dual LED blinker ready\n");
    printf("LED1: GPIO4, 1000 ms period (500/500)\n");
    printf("LED2: GPIO5,  400 ms period (200/200)\n");

    xTaskCreate(task_led1, "task_led1", 2048, NULL, 5, NULL);
    xTaskCreate(task_led2, "task_led2", 2048, NULL, 5, NULL);

    // Keep app_main alive without busy-waiting (avoid task watchdog reset).
    while (1) {
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}
